export const __metadata = { PACKAGE_NAME: '@wix/data' };

export function publishDataItemDraft(
  httpClient: HttpClient
): PublishDataItemDraftSignature {
  return (
    options: NonNullablePaths<
      PublishDataItemDraftOptions,
      `dataCollectionId` | `dataItemId`,
      2
    >
  ) =>
    universalPublishDataItemDraft(
      options,
      // @ts-ignore
      { httpClient }
    );
}

interface PublishDataItemDraftSignature {
  /**
   * Publishes a pending draft of a data item.
   *
   *
   * This method replaces the published item's data with the draft's content. On success, the draft is deleted.
   *
   * Pass the **published** collection ID as `dataCollectionId` (for example, `articles`).
   *
   * To author a brand-new draft, call [Insert Data Item](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/insert-data-item) with `dataCollectionId` set to your collection's drafts shadow (for example, `articles__drafts` when the published collection ID is `articles`). Edit the draft via [Update Data Item](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/update-data-item) or [Patch Data Item](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/patch-data-item) against the same drafts shadow collection ID.
   *
   * To retract a published item back to draft state, call [Unpublish Data Item](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/unpublish-data-item).
   *
   * > **Notes:**
   * > - Returns `NOT_FOUND` if no pending draft exists for the supplied `dataItemId`.
   * > - Calling this method triggers domain events on both collections: a [Data Item Created](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/data-item-created) or [Data Item Updated](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/data-item-updated) event on the published collection, and a [Data Item Deleted](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/data-item-deleted) event on the drafts shadow collection.
   */
  (
    options: NonNullablePaths<
      PublishDataItemDraftOptions,
      `dataCollectionId` | `dataItemId`,
      2
    >
  ): Promise<
    NonNullablePaths<
      PublishDataItemDraftResponse,
      `dataItem._id` | `dataItem.dataCollectionId`,
      3
    >
  >;
}

export function unpublishDataItem(
  httpClient: HttpClient
): UnpublishDataItemSignature {
  return (
    options?: NonNullablePaths<
      UnpublishDataItemOptions,
      `dataCollectionId` | `dataItemId`,
      2
    >
  ) =>
    universalUnpublishDataItem(
      options,
      // @ts-ignore
      { httpClient }
    );
}

interface UnpublishDataItemSignature {
  /**
   * Retracts a published data item back to draft state.
   *
   *
   * This method removes the published copy of the item and creates a draft seeded with the previously-published data. Use it to take a published item offline so it can be edited.
   *
   * Pass the **published** collection ID as `dataCollectionId` (for example, `articles`).
   *
   * After unpublishing, edit the resulting draft via [Update Data Item](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/update-data-item) or [Patch Data Item](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/patch-data-item) with `dataCollectionId` set to your collection's drafts shadow (for example, `articles__drafts`). To put the item back live, call [Publish Data Item Draft](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/publish-data-item-draft).
   *
   * Set `copyToDraft` to `false` to remove the published item without creating a draft.
   *
   * > **Notes:**
   * > - If a pending draft already exists for the supplied `dataItemId`, it is silently overwritten with the previously-published data.
   * > - The response carries the newly-created (or overwritten) draft, not the previously-published item.
   * > - Returns `NOT_FOUND` if no published item exists with the supplied `dataItemId`.
   * > - Calling this method always triggers a [Data Item Deleted](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/data-item-deleted) event on the published collection. When `copyToDraft` is `true` (the default), it also triggers a [Data Item Created](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/data-item-created) or [Data Item Updated](https://dev.wix.com/docs/rest/business-solutions/cms/data-items/data-item-updated) event on the drafts shadow collection. When `copyToDraft` is `false`, no draft is created and no events fire on the drafts shadow collection.
   */
  (
    options?: NonNullablePaths<
      UnpublishDataItemOptions,
      `dataCollectionId` | `dataItemId`,
      2
    >
  ): Promise<
    NonNullablePaths<
      UnpublishDataItemResponse,
      `dataItem._id` | `dataItem.dataCollectionId`,
      3
    >
  >;
}

export const onDataItemCreated = EventDefinition(
  'wix.data.v2.data_item_created',
  true,
  (event: DataItemCreatedEnvelope) =>
    renameKeysFromRESTResponseToSDKResponse(
      transformPaths(event, [
        {
          transformFn: transformRESTTimestampToSDKTimestamp,
          paths: [{ path: 'metadata.eventTime' }],
        },
      ]),
      ['entity.data']
    )
)<DataItemCreatedEnvelope>();
export const onDataItemDeleted = EventDefinition(
  'wix.data.v2.data_item_deleted',
  true,
  (event: DataItemDeletedEnvelope) =>
    renameKeysFromRESTResponseToSDKResponse(
      transformPaths(event, [
        {
          transformFn: transformRESTTimestampToSDKTimestamp,
          paths: [{ path: 'metadata.eventTime' }],
        },
      ]),
      ['entity.data']
    )
)<DataItemDeletedEnvelope>();
export const onDataItemUpdated = EventDefinition(
  'wix.data.v2.data_item_updated',
  true,
  (event: DataItemUpdatedEnvelope) =>
    renameKeysFromRESTResponseToSDKResponse(
      transformPaths(event, [
        {
          transformFn: transformRESTTimestampToSDKTimestamp,
          paths: [{ path: 'metadata.eventTime' }],
        },
      ]),
      ['entity.data']
    )
)<DataItemUpdatedEnvelope>();

